/* Cara Ia Dilakukan opening: a faceless woman's head with long layered hair, side-swept bangs and flipped ends,
   as small particles. Same format as the home head; read by the particle opening when .pz has data-shape="woman". */
window.__womanCloud = function (N) {
  var raw = atob(''), NH = 20640, NS = 3360, n = raw.length / 4;
  var nh = Math.min(NH, Math.round(N * NH / (NH + NS))), ns = Math.min(NS, N - nh);
  var head = new Float32Array(N * 3), kind = new Float32Array(N), seed = 3;
  var rnd = function () { seed = (seed * 16807) % 2147483647; return (seed - 1) / 2147483646; };
  var put = function (k, j) {
    head[k * 3] = -1.1 + raw.charCodeAt(j * 4) / 255 * 2.2 + (rnd() - .5) * .009;
    head[k * 3 + 1] = -2.35 + raw.charCodeAt(j * 4 + 1) / 255 * 3.7 + (rnd() - .5) * .014;
    head[k * 3 + 2] = -1.0 + raw.charCodeAt(j * 4 + 2) / 255 * 2.0 + (rnd() - .5) * .008;
  };
  var k = 0;
  for (var i = 0; i < nh; i++, k++) { put(k, i); kind[k] = 1 + raw.charCodeAt(i * 4 + 3) / 255; }
  for (i = 0; i < ns && k < N; i++, k++) { put(k, NH + i); kind[k] = 0; }
  for (; k < N; k++) { put(k, k % NH); kind[k] = 1; }
  return { head: head, kind: kind };
};
